#!/bin/bash
set -uo pipefail

# Test: Prime runtime QA regression pins — autosave gate,
#       activity-data read-only sync, prime settings, greeting graph-source
# Generated by /qa on 2026-08-07 for dev/oguzhan/handoff-definition-unify
# Covers: bin/attendant.sh, bin/lib/greeting.sh, bin/codex-session-start.sh,
#         bin/activity-data.sh, bin/lib/context.sh, .prime/agent/settings.json

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1" >&2; }

echo "Testing: Prime runtime QA regression pins"
echo ""

# --- 2. Autosave greeting gate present in BOTH harness paths ---
for f in bin/lib/greeting.sh bin/codex-session-start.sh; do
  if grep -q 'autosave_enabled // false' "$SCRIPT_DIR/$f"; then
    pass "$f gates the awaiting-merge line on autosave_enabled"
  else
    fail "$f missing the autosave_enabled gate"
  fi
done

# --- 3. activity-data.sh: data reads never mutate the working branch ---
if grep -qE 'git .* rebase' "$SCRIPT_DIR/bin/activity-data.sh"; then
  fail "activity-data.sh reintroduced a rebase (data reads must not mutate branches)"
else
  pass "activity-data.sh contains no branch rebase"
fi
if grep -q 'fetch origin develop:develop' "$SCRIPT_DIR/bin/activity-data.sh"; then
  fail "activity-data.sh still force-updates the local develop ref"
else
  pass "activity-data.sh no longer touches the local develop ref"
fi

# --- 4. Prime settings: shared corpus + deduped skill commands, bundle in sync ---
SET="$SCRIPT_DIR/.prime/agent/settings.json"
if jq -e '.skills == ["../../.codex/skills"]' "$SET" >/dev/null 2>&1; then
  pass "prime settings point at the shared corpus (two levels up)"
else
  fail "prime settings corpus path wrong"
fi
if jq -e '.enableSkillCommands == false' "$SET" >/dev/null 2>&1; then
  pass "prime settings disable duplicate /skill: commands"
else
  fail "prime settings missing enableSkillCommands=false"
fi
BUNDLE_SET="$SCRIPT_DIR/packages/create-egregore/runtime/prime/.prime/agent/settings.json"
if cmp -s "$SET" "$BUNDLE_SET"; then
  pass "bundled prime settings identical to source"
else
  fail "bundled prime settings drifted from source"
fi

# --- 5. Greeting addressed list: graph-sourced with file fallback ---
CTX="$SCRIPT_DIR/bin/lib/context.sh"
if grep -q 'graph-op.sh" open-handoffs' "$CTX"; then
  pass "greeting sources addressed handoffs from the canonical named read"
else
  fail "greeting no longer uses open-handoffs"
fi
if grep -q 'LOCAL_MODE:-false' "$CTX" && grep -A2 'if \[ -z "\$ADDRESSED" \]' "$CTX" | grep -q 'grep -rli'; then
  pass "greeting keeps the local/offline file-grep fallback"
else
  fail "greeting fallback to file grep missing"
fi

# --- 6. Focus prompts: complete-data file + no-narration + no (untitled) ---
for f in .prime/agent/extensions/egregore.ts .pi/extensions/egregore.ts; do
  if grep -q 'activityDataPath' "$SCRIPT_DIR/$f" && \
     grep -q 'never print (untitled)' "$SCRIPT_DIR/$f" && \
     grep -q 'Output nothing except the final rendered result' "$SCRIPT_DIR/$f"; then
    pass "$f focus prompt: file data + quiet + untitled fallback"
  else
    fail "$f focus prompt missing a required rule"
  fi
done

# --- Summary ---
echo ""
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
